-- [CLAUDE] 21.10.2026 Leistung: km-Rücksprung (Ablesung kleiner als die unmittelbar vorherige nach measured_at, rowid) gespeichert statt
-- bei jedem Aufruf per LAG() über die gesamte km-Historie gerechnet (Lastmessung 150 Lkw / 220 000 km-Stände: Fahrzeugliste 431 → ~40 ms,
-- Startseiten, /v1/availability, Prüftermine, Datenqualität). km_drop_prev = km der vorherigen Ablesung, wenn diese größer war, sonst NULL.
-- Gepflegt per Trigger bei jedem Einfügen (neue Zeile und ihre unmittelbare Nachfolgerin, auch wenn nachträglich zwischen ältere einsortiert)
-- und Löschen (Nachfolgerin). Änderungen bestehender Zeilen gibt es in der App nicht; der Änderungs-Trigger rechnet das Fahrzeug neu.
ALTER TABLE odometer_readings ADD COLUMN km_drop_prev INTEGER NULL;
UPDATE odometer_readings SET km_drop_prev = w.prev_km FROM (SELECT rowid AS rid, km, LAG(km) OVER (PARTITION BY vehicle_id ORDER BY measured_at, rowid) AS prev_km FROM odometer_readings) AS w WHERE w.rid = odometer_readings.rowid AND w.km < w.prev_km;
CREATE INDEX IF NOT EXISTS idx_odometer_drop ON odometer_readings(vehicle_id, measured_at) WHERE km_drop_prev IS NOT NULL;
CREATE TRIGGER IF NOT EXISTS trg_odometer_drop_ins AFTER INSERT ON odometer_readings BEGIN UPDATE odometer_readings SET km_drop_prev = (SELECT CASE WHEN odometer_readings.km < p.km THEN p.km END FROM odometer_readings p WHERE p.vehicle_id = odometer_readings.vehicle_id AND (p.measured_at < odometer_readings.measured_at OR (p.measured_at = odometer_readings.measured_at AND p.rowid < odometer_readings.rowid)) ORDER BY p.measured_at DESC, p.rowid DESC LIMIT 1) WHERE rowid IN (NEW.rowid, (SELECT s.rowid FROM odometer_readings s WHERE s.vehicle_id = NEW.vehicle_id AND (s.measured_at > NEW.measured_at OR (s.measured_at = NEW.measured_at AND s.rowid > NEW.rowid)) ORDER BY s.measured_at, s.rowid LIMIT 1)); END;
CREATE TRIGGER IF NOT EXISTS trg_odometer_drop_del AFTER DELETE ON odometer_readings BEGIN UPDATE odometer_readings SET km_drop_prev = (SELECT CASE WHEN odometer_readings.km < p.km THEN p.km END FROM odometer_readings p WHERE p.vehicle_id = odometer_readings.vehicle_id AND (p.measured_at < odometer_readings.measured_at OR (p.measured_at = odometer_readings.measured_at AND p.rowid < odometer_readings.rowid)) ORDER BY p.measured_at DESC, p.rowid DESC LIMIT 1) WHERE rowid = (SELECT s.rowid FROM odometer_readings s WHERE s.vehicle_id = OLD.vehicle_id AND (s.measured_at > OLD.measured_at OR (s.measured_at = OLD.measured_at AND s.rowid > OLD.rowid)) ORDER BY s.measured_at, s.rowid LIMIT 1); END;
CREATE TRIGGER IF NOT EXISTS trg_odometer_drop_upd AFTER UPDATE OF km, measured_at, vehicle_id ON odometer_readings BEGIN UPDATE odometer_readings SET km_drop_prev = (SELECT CASE WHEN odometer_readings.km < p.km THEN p.km END FROM odometer_readings p WHERE p.vehicle_id = odometer_readings.vehicle_id AND (p.measured_at < odometer_readings.measured_at OR (p.measured_at = odometer_readings.measured_at AND p.rowid < odometer_readings.rowid)) ORDER BY p.measured_at DESC, p.rowid DESC LIMIT 1) WHERE vehicle_id IN (NEW.vehicle_id, OLD.vehicle_id); END;
